WITH with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC) AS prev_paid_at FROM payments), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL 30 DAYS THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessionized AS (SELECT id, order_id, amount, paid_at, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 7 THEN 'HIGH' ELSE 'LOW' END AS burst_id_tier, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min, COUNT(DISTINCT order_id) AS distinct_order_ids, (UNIX_TIMESTAMP(MAX(paid_at)) - UNIX_TIMESTAMP(MIN(paid_at))) / 60 AS duration_min_2 FROM sessionized GROUP BY burst_id_tier, quarter_start
